await setupComputerUseRuntime({globals:globalThis});
const {readFile,writeFile}=await import('node:fs/promises');
const f=JSON.parse(await readFile('{{e2eRuntimeRoot}}/cua-r2/manifest.json','utf8'));
const c=agent.computerUse.computer,ref={pid:f.pid,window_id:f.targetWindow};
const kind="left_click",method="left_click",trial=0;
const indexPath='{{e2eRuntimeRoot}}/cua-r2/'+kind+'-index.json';
const state=await c.get_app_state({app_ref:ref});
if(typeof state!=='string')throw new Error('R2_STATE_MISSING:'+JSON.stringify({ref,state,windows:await c.list_windows({app_ref:{pid:f.pid}})}));
const elements=state.split('\n').flatMap(line=>{try{return [JSON.parse(line)]}catch{return []}});
const element=elements.find(e=>method==='set_value'?e.kind==='AXTextField':(e.title==='R2 Press'||e.title==='E2E_R2_PRESS')&&e.actions?.includes('AXPress'));
if(!element||!Number.isSafeInteger(element.index))throw new Error('R2_ELEMENT_MISSING');
await writeFile(indexPath,JSON.stringify({index:element.index}),{mode:0o600});
const mode=['none','compact','full'][trial];
const args={app_ref:ref,target:{type:'element',index:element.index},return_state:mode};
if(method==='perform_action')args.action='AXPress';
if(method==='set_value')args.value='E2E_R2_VALUE_'+trial;
const result=await c[method](args);
const r=result?.content?JSON.parse(result.content[0].text):result;
if(mode!=='none'&&(!result?.structuredContent?.state_id||result.structuredContent.app?.pid!==f.pid||result.structuredContent.window?.window_id!==f.targetWindow||JSON.stringify(result.structuredContent).includes(f.siblingMarker)))throw new Error('R2_RETURN_STATE_MISSING');
if(kind==='deny'){
 if(r?.code!=='permission_denied'||r.action_sent!==false||r.dispatch_status!=='not_sent')throw new Error('R2_DENIAL_MISSING');
}else if(r?.code||r?.action_sent!==true||r?.dispatch_status!=='sent')throw new Error('R2_WRITE_NOT_PROVEN:'+JSON.stringify(r));
if(r.state_sync_status!==(mode==='none'?'not_requested':'synced'))throw new Error('R2_RETURN_STATE_STATUS_MISMATCH');
nodeRepl.write('R2_RECEIPTS:'+JSON.stringify({kind,trial,return_state:mode,receipts:[r]}));

